var TRANSPORTS = ['stdio','sse','http'];
function validateServer(name, cfg){
  var errs=[], warns=[];
  if(!name || !/^[A-Za-z0-9_-]+$/.test(name)) errs.push('服务器名只能包含字母、数字、连字符和下划线');
  if(!cfg || typeof cfg!=='object'){ errs.push('配置必须是对象'); return {valid:false, errors:errs, warnings:warns}; }
  var hasCmd = typeof cfg.command === 'string' && cfg.command.length>0;
  var hasUrl = typeof cfg.url === 'string' && cfg.url.length>0;
  if(!hasCmd && !hasUrl) errs.push('必须提供 command（stdio）或 url（sse/http）');
  if(hasCmd && hasUrl) warns.push('同时提供 command 与 url，客户端行为未定义');
  if(cfg.args !== undefined && !Array.isArray(cfg.args)) errs.push('args 必须是数组');
  if(cfg.env !== undefined && (typeof cfg.env!=='object' || Array.isArray(cfg.env))) errs.push('env 必须是对象');
  if(hasUrl && !/^https?:\/\//.test(cfg.url)) errs.push('url 必须以 http:// 或 https:// 开头');
  if(hasUrl && /^http:\/\//.test(cfg.url) && !/^http:\/\/(localhost|127\.0\.0\.1)/.test(cfg.url))
    warns.push('非本地地址建议使用 https，避免凭据明文传输');
  if(cfg.env){
    for(var k in cfg.env){
      if(!cfg.env.hasOwnProperty(k)) continue;
      var v=String(cfg.env[k]);
      if(/^(gh[pousr]_|sk-|xox[baprs]-|AKIA)/.test(v)) warns.push('env.'+k+' 疑似硬编码真实密钥，建议改用 ${ENV_VAR} 占位');
    }
  }
  return {valid: errs.length===0, errors:errs, warnings:warns};
}
function detectTransport(cfg){
  if(!cfg || typeof cfg!=='object') return 'unknown';
  if(typeof cfg.command === 'string' && cfg.command) return 'stdio';
  if(typeof cfg.url === 'string' && /\/sse\b/.test(cfg.url)) return 'sse';
  if(typeof cfg.url === 'string' && cfg.url) return 'http';
  return 'unknown';
}
function buildConfig(servers){
  var out={mcpServers:{}};
  for(var i=0;i<servers.length;i++){
    var s=servers[i];
    if(!s || !s.name) continue;
    var c={};
    if(s.command){ c.command=s.command; if(s.args && s.args.length) c.args=s.args; }
    else if(s.url){ c.url=s.url; }
    if(s.env && Object.keys(s.env).length) c.env=s.env;
    out.mcpServers[s.name]=c;
  }
  return out;
}
function parseArgs(str){
  if(!str) return [];
  var out=[], cur='', q=null;
  for(var i=0;i<str.length;i++){
    var ch=str.charAt(i);
    if(q){ if(ch===q){ q=null; } else { cur+=ch; } }
    else if(ch==='"' || ch==="'"){ q=ch; }
    else if(ch===' '){ if(cur){ out.push(cur); cur=''; } }
    else { cur+=ch; }
  }
  if(cur) out.push(cur);
  return out;
}
function parseEnv(str){
  var out={};
  if(!str) return out;
  var lines=String(str).split(/\r?\n/);
  for(var i=0;i<lines.length;i++){
    var ln=lines[i].trim();
    if(!ln || ln.charAt(0)==='#') continue;
    var eq=ln.indexOf('=');
    if(eq<1) continue;
    out[ln.slice(0,eq).trim()]=ln.slice(eq+1).trim();
  }
  return out;
}
function auditConfig(obj){
  var res={servers:[], totalErrors:0, totalWarnings:0};
  if(!obj || typeof obj!=='object' || !obj.mcpServers){
    return {servers:[], totalErrors:1, totalWarnings:0, fatal:'缺少顶层 mcpServers 字段'};
  }
  for(var name in obj.mcpServers){
    if(!obj.mcpServers.hasOwnProperty(name)) continue;
    var cfg=obj.mcpServers[name];
    var v=validateServer(name, cfg);
    res.servers.push({name:name, transport:detectTransport(cfg), valid:v.valid, errors:v.errors, warnings:v.warnings});
    res.totalErrors += v.errors.length;
    res.totalWarnings += v.warnings.length;
  }
  return res;
}
if (typeof module !== 'undefined' && module.exports) { module.exports = { validateServer:validateServer, detectTransport:detectTransport, buildConfig:buildConfig, parseArgs:parseArgs, parseEnv:parseEnv, auditConfig:auditConfig, TRANSPORTS:TRANSPORTS }; }
if (typeof window !== 'undefined') { window.McpForgePure = { validateServer:validateServer, detectTransport:detectTransport, buildConfig:buildConfig, parseArgs:parseArgs, parseEnv:parseEnv, auditConfig:auditConfig, TRANSPORTS:TRANSPORTS }; }
